/* Course chapters: one idea at a time, then one source-book mission at a time. */
(()=>{
  'use strict';
  const instances=new WeakMap();
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const plain=value=>Array.isArray(value)?value.join('；'):String(value??'');
  const bounded=(n,length)=>Math.max(0,Math.min(Math.max(0,length-1),Number.isInteger(+n)?+n:0));
  function url(value){const s=String(value??'').trim();if(!s||/^(?:javascript|data|vbscript):/i.test(s))return '';try{const u=new URL(s,location.href);return ['http:','https:','file:'].includes(u.protocol)?s:''}catch{return ''}}
  const normalize=value=>String(value??'').normalize('NFKC').trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ');
  const itemKey=(item,index)=>String(item.id??`item-${index+1}`);
  const multiple=item=>Array.isArray(item.answer);
  const automatic=item=>Array.isArray(item.options)&&item.options.length>0||item.autoGrade===true||item.answerMode==='exact';
  function same(actual,item){if(multiple(item)){let values;try{values=JSON.parse(actual)}catch{values=[]}return Array.isArray(values)&&values.length===item.answer.length&&[...values].map(normalize).sort().join('\u001f')===[...item.answer].map(normalize).sort().join('\u001f')}return [item.answer,...(Array.isArray(item.alternatives)?item.alternatives:[])].some(value=>normalize(actual)===normalize(value))}
  function expected(item){const values=Array.isArray(item.answer)?item.answer:[item.answer];return values.map(value=>{const option=(item.options||[]).find(o=>String(o.value)===String(value));return option?plain(option.label):plain(value)}).join('；')}
  function render(host,options){
    if(!host||!options?.lesson||!options?.state)throw Error('StudyChapters.render requires host, lesson and state.');
    instances.get(host)?.destroy();
    const {lesson,course=null,state}=options,rules=Array.isArray(lesson.rules)?lesson.rules:[],missions=Array.isArray(course?.missions)?course.missions:[],hasBook=missions.length>0,id=String(lesson.id),courseId=String(course?.id??id);
    for(const key of ['tasks','drafts','results','read'])if(!state[key]||typeof state[key]!=='object'||Array.isArray(state[key]))throw Error(`Missing state.${key}`);
    const positionKey=`chapter:${id}:position`,abort=new AbortController();
    let view='overview',step=0,missionIndex=0,itemIndex=0,sourcePage=0,answerPage=0,zoomKind='source',zoomOriginal=false,destroyed=false;
    let savedPosition={};try{savedPosition=JSON.parse(state.drafts[positionKey]||'{}')}catch{}
    if(!savedPosition||typeof savedPosition!=='object')savedPosition={};
    const learned=i=>state.tasks[`learn:${id}:${i}`]===true;
    const missionKey=m=>`book:${courseId}:${m.id}`;
    const draftKey=(m,suffix)=>`${missionKey(m)}:${suffix}`;
    const result=m=>state.results[missionKey(m)];
    const partial=m=>Boolean(m.items?.length&&(m.itemsPartial===true||course?.itemsPartial===true));
    const notify=text=>options.toast?.(text);
    function save(activity=false){try{const pending=options.save?.(Boolean(activity));pending?.catch?.(()=>notify('作答仍保留在当前页面；保存暂未成功，请稍后重试。'))}catch{notify('作答仍保留在当前页面；保存暂未成功，请稍后重试。')}}
    function persistPosition(){savedPosition={view,step,missionIndex,itemIndex,sourcePage,answerPage};state.drafts[positionKey]=JSON.stringify(savedPosition);save(false)}
    function syncRead(){const all=rules.length>0&&rules.every((_,i)=>learned(i));if(state.read[id]!==all){state.read[id]=all;return true}return false}
    if(syncRead())save(false);
    function award(key){const first=state.tasks[key]!==true;state.tasks[key]=true;if(first)options.reward?.();return first}
    function move(next,config={}){view=next;step=bounded(config.step??step,rules.length);missionIndex=bounded(config.missionIndex??missionIndex,missions.length);const m=missions[missionIndex];itemIndex=bounded(config.itemIndex??0,m?.items?.length||1);sourcePage=bounded(config.sourcePage??0,m?.sourcePages?.length||1);answerPage=bounded(config.answerPage??0,m?.answerPages?.length||1);persistPosition();draw();host.querySelector('#ch-view-title')?.focus({preventScroll:true})}
    function continueLearning(){const unfinished=rules.findIndex((_,i)=>!learned(i));const resume=savedPosition.view==='learn'&&rules[savedPosition.step]&&!learned(+savedPosition.step)?+savedPosition.step:unfinished;move('learn',{step:resume<0?0:resume})}
    function continuePractice(){let mi=savedPosition.view==='practice'?bounded(savedPosition.missionIndex,missions.length):missions.findIndex(m=>state.tasks[missionKey(m)]!==true);if(mi<0)mi=0;const m=missions[mi];let ii=0;if(m?.items?.length){const r=result(m);ii=m.items.findIndex((q,i)=>!r?.checked?.[itemKey(q,i)]?.reviewed);if(ii<0)ii=0}move('practice',{missionIndex:mi,itemIndex:ii,sourcePage:savedPosition.view==='practice'&&+savedPosition.missionIndex===mi?savedPosition.sourcePage:0})}
    function sourceLink(){const href=url(course?.sourcePdf);return href?`<a class="ch-text-link" href="${escape(href)}" target="_blank" rel="noopener">打开原书 PDF ↗</a>`:''}
    function header(){const learnCount=rules.filter((_,i)=>learned(i)).length,bookCount=missions.filter(m=>state.tasks[missionKey(m)]===true).length;return `<div class="ch-topline"><button class="ch-back" data-ch-action="back">← 全部专题</button><span class="ch-course-type">${hasBook?'COURSE × ORIGINAL BOOK':'SUPPLEMENTARY TOPIC'}</span></div><header class="ch-header"><div><div class="ch-kicker">${hasBook?'学习知识点，再挑战教材原题':'课程补充 · 分步学习'}</div><h1 id="ch-view-title" tabindex="-1">${escape(lesson.title)}</h1><p>${escape(lesson.subtitle||'先理解，再运用。每一步都能接着上次继续。')}</p></div>${sourceLink()}</header><nav class="ch-tabs" aria-label="专题分区"><button data-ch-action="overview" class="${view==='overview'?'active':''}" aria-current="${view==='overview'?'page':'false'}"><span>◈</span> 关卡总览</button><button data-ch-action="learn-tab" class="${view==='learn'?'active':''}" aria-current="${view==='learn'?'page':'false'}"><span>01</span> 学习 <small>${learnCount}/${rules.length}</small></button>${hasBook?`<button data-ch-action="practice-tab" class="${view==='practice'?'active':''}" aria-current="${view==='practice'?'page':'false'}"><span>02</span> 原书练习 <small>${bookCount}/${missions.length}</small></button>`:''}</nav>`}
    function missionStatus(m){const r=result(m);if(r?.submitted&&r.status==='complete')return r.reviewNeed?'review':'complete';if(r?.submitted)return 'assess';if(r?.checked&&Object.keys(r.checked).length||state.drafts[draftKey(m,'response')]||m.items?.some((q,i)=>state.drafts[draftKey(m,itemKey(q,i))]))return 'progress';return 'new'}
    const statusLabel=status=>({complete:'已完成',review:'待复习',assess:'待对照自评',progress:'继续练习',new:'尚未开始'}[status]||'尚未开始');
    function overview(){const count=rules.filter((_,i)=>learned(i)).length,complete=missions.filter(m=>state.tasks[missionKey(m)]===true).length,total=rules.length+missions.length,percent=total?Math.round((count+complete)/total*100):0;return `<section class="ch-launch"><div><span class="ch-kicker">YOUR NEXT STEP</span><h2>${count===0?'先理解一个知识点。':count<rules.length?'从上次的进度，继续。':hasBook?'知识已就位，去原书里用一次。':'本专题已完成，随时回来复习。'}</h2><p>${hasBook?'学习区把规则拆成小步；练习区保留教材原题和原答案。一次走好一小关。':'这是一份补充专题，提供知识点学习；当前没有已核对的原书练习关卡。'}</p><div class="ch-actions"><button class="ch-primary" data-ch-action="${count===rules.length&&hasBook?'practice-tab':'learn-tab'}">${count===rules.length&&hasBook?'进入原书练习':count?'继续学习':'开始学习'} <span>↗</span></button>${hasBook&&count<rules.length?'<button class="ch-secondary" data-ch-action="practice-tab">直接查看原书关卡</button>':''}</div><div class="ch-launch-meta"><span>${count} / ${rules.length} 个知识点</span>${hasBook?`<span>${complete} / ${missions.length} 个原书关卡</span>`:'<span>补充讲解 · 不冒充原题</span>'}</div></div><div class="ch-progress-dial" style="--ch-progress:${percent}"><div><strong>${percent}<small>%</small></strong><span>CHAPTER PROGRESS</span></div></div></section>${hasBook&&course.coverageNote?`<div class="ch-source-note"><strong>原页与答案说明</strong><p>${escape(plain(course.coverageNote))}</p></div>`:''}<div class="ch-map-columns"><section class="ch-map-panel"><div class="ch-section-heading"><span class="ch-section-number">01</span><div><h2>学习路径</h2><p>一个知识点，一次理解。</p></div></div><ol class="ch-learning-map">${rules.map((r,i)=>`<li><button class="ch-step-card ${learned(i)?'is-done':''}" data-ch-action="learn-step" data-index="${i}"><span class="ch-node">${learned(i)?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${escape(r.title||`知识点 ${i+1}`)}</strong><small>${learned(i)?'已学 · 可再次回顾':'规则讲解 · 例句拆解'}</small></span><span class="ch-step-arrow">↗</span></button></li>`).join('')||'<li class="ch-empty">本专题暂未提供知识点。</li>'}</ol></section><section class="ch-map-panel"><div class="ch-section-heading"><span class="ch-section-number violet">02</span><div><h2>${hasBook?'原书挑战':'应用与拓展'}</h2><p>${hasBook?'先作答，再查看原书答案。':'先把知识学会，再按需拓展。'}</p></div></div>${hasBook?`<div class="ch-book-map">${missions.map((m,i)=>{const status=missionStatus(m);return `<button class="ch-mission-card ${status}" data-ch-action="mission" data-index="${i}"><span class="ch-mission-order">${String(i+1).padStart(2,'0')}</span><span class="ch-mission-info"><strong>${escape(m.title||`关卡 ${i+1}`)}</strong><small>${escape(plain(m.bookPages)||'教材原题')} · ${m.items?.length?`${m.items.length} 项${partial(m)?'部分题核对':'分步作答'}`:'原页作答与自评'}</small></span><span class="ch-status ${status}">${statusLabel(status)}</span></button>`}).join('')}</div>`:'<div class="ch-supplement-note"><span>◇</span><h3>这部分是补充知识</h3><p>本页不会用自编题冒充教材原题。完成学习后，可返回核心教材继续原书训练。</p></div>'}</section></div><div class="ch-coverage"><strong>${hasBook?'来源与覆盖':'关于本专题'}</strong><p>${escape(hasBook?course.coverageNote||`练习来自 ${course.sourceTitle||lesson.title}。保留原书页图，页面标签区分教材页码与 PDF 页码。`:lesson.source||'课程补充讲解。')}</p>${sourceLink()}${typeof options.onSupplement==='function'?'<button class="ch-text-link" data-ch-action="supplement">可选：查看原创补充自测 ↗</button>':''}</div>`}
    function learnView(){if(!rules.length)return '<section class="ch-panel ch-empty"><h2>暂未提供知识点</h2><button class="ch-secondary" data-ch-action="overview">返回总览</button></section>';const r=rules[step],last=step===rules.length-1,remaining=rules.filter((_,i)=>i!==step&&!learned(i)).length;const nextLabel=!last?'理解了，下一知识点':remaining?'完成本点，补齐未学内容':hasBook?'完成学习，进入原书练习':'完成本专题学习';return `<div class="ch-learn-layout"><aside class="ch-step-rail" aria-label="知识点目录">${rules.map((q,i)=>`<button class="ch-rail-step ${i===step?'active':''} ${learned(i)?'is-done':''}" data-ch-action="learn-step" data-index="${i}" ${i===step?'aria-current="step"':''}><span>${learned(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${escape(q.title)}</span></button>`).join('')}</aside><article class="ch-panel ch-learn-card"><div class="ch-card-top"><span class="ch-kicker">LEARN ${String(step+1).padStart(2,'0')} / ${String(rules.length).padStart(2,'0')}</span><span class="ch-status ${learned(step)?'complete':'new'}">${learned(step)?'已学会 · 回顾中':'待学习'}</span></div><h2>${escape(r.title)}</h2><p class="ch-explanation">${escape(r.explanation)}</p>${r.example?`<section class="ch-rule-example"><span class="ch-mini-label">EXAMPLE · 讲解示例</span><p>${escape(r.example)}</p></section>`:''}${r.before||r.after?`<div class="ch-comparison">${r.before?`<section class="ch-before"><span>改前 · 留意问题</span><p>${escape(r.before)}</p></section>`:''}${r.after?`<section class="ch-after"><span>改后 · 看清结构</span><p>${escape(r.after)}</p></section>`:''}</div>`:''}<div class="ch-reflection"><span>✦</span><p>用自己的话说出这条规则，再试着口头造一个句子。理解后，继续下一步。</p></div><div class="ch-learn-footer"><button class="ch-secondary" data-ch-action="previous-step" ${step===0?'disabled':''}>← 上一知识点</button><button class="ch-primary" data-ch-action="learn-next">${nextLabel} →</button></div><div class="ch-footnote">本区为中文学习讲解；讲解示例不等同于教材原题。${hasBook?'原书题目在「原书练习」中。':''}</div></article></div>`}
    function pages(m,kind){return Array.isArray(kind==='answer'?m.answerPages:m.sourcePages)?kind==='answer'?m.answerPages:m.sourcePages:[]}
    function imageViewer(m,kind){const all=pages(m,kind),index=bounded(kind==='answer'?answerPage:sourcePage,all.length),p=all[index];if(!p)return `<div class="ch-page-missing"><span>▤</span><p>${kind==='source'?'本关请按指定页码打开原书 PDF 作答。':'本关未提供可预览的答案页图。'}</p>${kind==='source'?sourceLink():url(course.answerPdf)?`<a class="ch-text-link" href="${escape(url(course.answerPdf))}" target="_blank" rel="noopener">打开原书答案 PDF ↗</a>`:'<p>请按教材要求或向教师核对；不要把开放表达当作唯一标准答案。</p>'}</div>`;return `<section class="ch-page-viewer" data-viewer="${kind}"><div class="ch-page-head"><div><span class="ch-mini-label">${kind==='answer'?'ANSWER KEY':'SOURCE BOOK'}</span><strong>${escape(p.label||`${kind==='answer'?'答案':'原书'} PDF 第 ${p.page??index+1} 页`)}</strong></div><button class="ch-text-link" data-ch-action="zoom" data-kind="${kind}">放大阅读 ⤢</button></div><button class="ch-page-image" data-ch-action="zoom" data-kind="${kind}" aria-label="放大${escape(p.label||'教材原页')}"><img src="${escape(url(p.src))}" alt="${escape(p.label||`${m.title} ${kind==='answer'?'答案':'题目'}第${index+1}页`)}" decoding="async" loading="lazy"><span class="ch-image-error" hidden>页图暂未加载，请打开原 PDF 查看。</span><span class="ch-image-zoom">点击放大原页</span></button><div class="ch-page-controls"><button class="ch-icon-button" data-ch-action="page-prev" data-kind="${kind}" aria-label="上一${kind==='answer'?'答案':'原书'}页" ${index===0?'disabled':''}>←</button><span>${index+1} / ${all.length} 页</span><button class="ch-icon-button" data-ch-action="page-next" data-kind="${kind}" aria-label="下一${kind==='answer'?'答案':'原书'}页" ${index>=all.length-1?'disabled':''}>→</button></div></section>`}
    function currentItems(m){return Array.isArray(m.items)?m.items:[]}
    function answered(m,q,index){const value=state.drafts[draftKey(m,itemKey(q,index))]||'';if(multiple(q)){try{return JSON.parse(value).length>0}catch{return false}}return value.trim().length>0}
    function itemView(m){const items=currentItems(m),q=items[itemIndex],key=itemKey(q,itemIndex),r=result(m),checked=r?.checked?.[key],draft=state.drafts[draftKey(m,key)]||'',auto=automatic(q),multi=multiple(q);let selected=[];if(multi)try{selected=JSON.parse(draft)}catch{}const locked=Boolean(checked?.submitted);return `<section class="ch-item-card"><div class="ch-card-top"><span class="ch-mini-label">QUESTION ${itemIndex+1} / ${items.length}</span><span class="ch-mode-label">${auto?'客观题 · 提交后自动核对':'开放题 · 对照自评'}${multi?' · 多选':''}</span></div><div class="ch-item-progress" aria-label="题目进度">${items.map((x,i)=>{const c=r?.checked?.[itemKey(x,i)];return `<button class="${i===itemIndex?'active':''} ${c?.reviewed?c.correct?'correct':'incorrect':''}" data-ch-action="item-go" data-index="${i}" aria-label="第 ${i+1} 题${c?.reviewed?c.correct?'，已完成':'，待复习':''}">${i+1}</button>`}).join('')}</div><h3 class="ch-question-prompt">${escape(q.prompt)}</h3>${q.sourceLabel?`<p class="ch-item-source">原题定位：${escape(q.sourceLabel)}</p>`:''}${q.options?.length?`<fieldset class="ch-options" ${locked?'disabled':''}><legend class="ch-sr-only">${multi?'选择所有符合的答案':'选择一个答案'}</legend>${q.options.map((o,i)=>{const chosen=multi?selected.map(String).includes(String(o.value)):draft===String(o.value);return `<label class="ch-option ${chosen?'selected':''}"><input type="${multi?'checkbox':'radio'}" name="chapter-option" value="${escape(o.value)}" data-ch-input="option" ${chosen?'checked':''}><span class="ch-option-letter">${String.fromCharCode(65+i)}</span><span>${escape(o.label)}</span></label>`}).join('')}</fieldset>`:`<label class="ch-answer-label" for="ch-item-response">你的作答</label><textarea id="ch-item-response" rows="4" data-ch-input="item" placeholder="先独立写下答案，再提交核对。" ${locked?'readonly':''}>${escape(draft)}</textarea>`}${checked?.submitted?`<div class="ch-item-feedback ${checked.reviewed?checked.correct?'correct':'incorrect':'pending'}" role="status"><strong>${checked.reviewed?checked.kind==='auto'?checked.correct?'✓ 回答正确':'再留意这个知识点':checked.correct?'✓ 已自评掌握':'已标记待复习':'已提交，请对照参考自行判断'}</strong><div class="ch-reference-answer"><span>参考答案</span><p>${escape(expected(q)||'请结合原书答案页与题目要求核对。')}</p></div>${q.explanation?`<p>${escape(q.explanation)}</p>`:''}${!auto&&!checked.reviewed?`<p class="ch-self-disclaimer">这是开放作答，系统没有自动判断正误。请检查含义、结构与题目要求，合理的不同表达也可以成立。</p><div class="ch-actions"><button class="ch-primary" data-ch-action="self-item" data-choice="mastered">我已掌握</button><button class="ch-secondary" data-ch-action="self-item" data-choice="review">还需复习</button></div>`:''}</div>`:''}<div class="ch-item-footer">${!locked?`<button class="ch-primary" data-ch-action="check-item" ${!answered(m,q,itemIndex)?'disabled':''}>${auto?'提交本题，核对答案':'提交本题，对照参考'} →</button>`:`${checked.reviewed?`<button class="ch-primary" data-ch-action="next-item">${itemIndex<items.length-1?'下一题 →':items.some((x,i)=>!r?.checked?.[itemKey(x,i)]?.reviewed)?'继续未完成题目 →':partial(m)&&!r?.submitted?'继续整组原题 ↓':'查看本关结果 ↓'}</button>`:''}<button class="ch-text-link" data-ch-action="edit-item">重新作答本题</button>`}</div><p class="ch-save-hint">作答随输入保存。重练不会重复获得完成奖励。</p></section>`}
    function openResponse(m){const r=result(m),draft=state.drafts[draftKey(m,'response')]||'',submitted=r?.submitted,part=partial(m),itemsReady=!part||Boolean(r?.itemsSubmitted);return `<section class="ch-item-card ch-open-response"><span class="ch-mini-label">YOUR RESPONSE · ${part?'整组原题作答区':'原题作答区'}</span><h3>${part?'剩余原题，也要亲手完成。':'先独立完成，再揭晓答案。'}</h3><p class="ch-open-note">${part?'上方仅核对原组中的部分题；请在这里按题号完成整组其余题目，并记录需要复盘的地方。':'按照原页题号记录答案。'}改写、段落写作等允许多种合理表达，本关采用原书对照与自评。</p><label class="ch-answer-label" for="ch-open-answer">我的答案 / 写作草稿</label><textarea id="ch-open-answer" data-ch-input="response" rows="9" placeholder="例如：\n1. ...\n2. ...\n\n请先作答，再提交查看原答案。" ${submitted?'readonly':''}>${escape(draft)}</textarea><div class="ch-response-meta"><span data-ch-response-count>${draft.trim().length} 字符</span><span>自动保存草稿</span></div>${!submitted?`<button class="ch-primary ch-full-button" data-ch-action="submit-open" ${!draft.trim()||!itemsReady?'disabled':''}>提交作答，解锁原书答案 →</button><p class="ch-save-hint">${!itemsReady?'请先完成上方分步题，再提交整组作答。':'提交后可对照参考，自行标记「已掌握」或「待复习」。'}</p>`:`<div class="ch-item-feedback pending" role="status"><strong>✓ 作答已提交，原书答案已解锁。</strong><p>本题是自评练习，系统没有自动批改。先查看下方答案页，再给自己的理解作标记。</p></div><div class="ch-actions"><button class="ch-primary" data-ch-action="open-answers">查看原书答案 ↓</button><button class="ch-text-link" data-ch-action="retry">重新作答</button></div>`}</section>`}
    function summary(m){const r=result(m);if(!r?.submitted)return '';const done=r.status==='complete',items=currentItems(m),autoTotal=items.filter(automatic).length,selfTotal=items.length-autoTotal+(partial(m)?1:0);const objective=autoTotal>0;return `<section class="ch-result-card ${done?(r.reviewNeed?'review':'complete'):'pending'}" id="ch-mission-result"><div class="ch-result-symbol">${done?r.reviewNeed?'↺':'✦':'◇'}</div><div class="ch-result-content"><span class="ch-mini-label">MISSION ${String(missionIndex+1).padStart(2,'0')} · ${done?'COMPLETE':'SELF REVIEW'}</span><h3>${done?r.reviewNeed?'这一关已完成，留待再练一次。':'这一关，已走稳。':'作答完成，最后做一次自评。'}</h3>${objective?`<p>客观题：<strong>${r.automaticScore??r.score} / ${autoTotal}</strong> 题正确。${selfTotal?`另有 ${selfTotal} 项开放题按你的自评记录。`:''}</p>`:`<p>${done?'本关结果来自你的自评，不是系统自动批改。':'对照原书参考，检查完整性、含义和结构，再记录本关结果。'}</p>`}${done?`<div class="ch-actions"><button class="ch-primary" data-ch-action="next-mission">${missionIndex<missions.length-1?'进入下一关 →':'回到关卡总览 ↗'}</button><button class="ch-secondary" data-ch-action="retry">重练本关</button><button class="ch-text-link" data-ch-action="review-toggle">${r.reviewNeed?'重新确认：我已掌握':'标记为待复习'}</button></div>`:(!items.length||partial(m))?'<div class="ch-self-assess"><button class="ch-primary" data-ch-action="self-mission" data-choice="mastered">已对照，我已掌握</button><button class="ch-secondary" data-ch-action="self-mission" data-choice="review">已对照，还需复习</button></div>':''}</div></section>`}
    function answerSection(m){if(!result(m)?.submitted)return '';return `<section class="ch-answer-section" id="ch-answer-section"><div class="ch-section-heading"><span class="ch-section-number violet">KEY</span><div><h2>原书答案 · 提交后解锁</h2><p>${escape(course.answerTitle||'与本关对应的原答案')}。开放题请关注评分思路，不要求逐字相同。</p></div>${url(course.answerPdf)?`<a class="ch-text-link" href="${escape(url(course.answerPdf))}" target="_blank" rel="noopener">答案 PDF ↗</a>`:''}</div>${imageViewer(m,'answer')}</section>`}
    function practiceView(){if(!hasBook)return '<section class="ch-panel ch-empty"><h2>本补充专题没有原书练习关卡</h2><button class="ch-primary" data-ch-action="learn-tab">学习本专题</button></section>';const m=missions[missionIndex],items=currentItems(m),r=result(m);itemIndex=bounded(itemIndex,items.length||1);return `<div class="ch-practice-layout"><aside class="ch-mission-rail" aria-label="原书关卡目录">${missions.map((q,i)=>{const status=missionStatus(q);return `<button class="ch-rail-mission ${i===missionIndex?'active':''}" data-ch-action="mission" data-index="${i}" ${i===missionIndex?'aria-current="step"':''}><span class="ch-rail-mission-number">${String(i+1).padStart(2,'0')}</span><strong>${escape(q.title)}</strong><small class="${status}">${statusLabel(status)}</small></button>`}).join('')}</aside><div class="ch-practice-main"><header class="ch-mission-heading"><div><span class="ch-kicker">ORIGINAL BOOK · MISSION ${String(missionIndex+1).padStart(2,'0')}</span><h2>${escape(m.title)}</h2><p>${escape(plain(m.bookPages)||'教材原题')} <span>·</span> ${items.length?`${items.length} 项${partial(m)?'部分题核对':'分步作答'}`:'原页练习 · 对照自评'}</p></div><button class="ch-text-link" data-ch-action="overview">返回地图 ↗</button></header>${m.answerNote?`<div class="ch-answer-note"><strong>本关答案说明</strong><p>${escape(plain(m.answerNote))}</p></div>`:''}${partial(m)?`<div class="ch-source-note"><strong>自动核对只覆盖原组的 ${items.length} 项</strong><p>其他原题保留在扫描页中。完成下方「整组原题作答区」并对照自评，才计为本关完成。</p></div>`:''}${m.instructions?`<div class="ch-instructions"><strong>本关怎么做</strong><p>${escape(plain(m.instructions))}</p></div>`:''}<div class="ch-practice-workspace"><div>${imageViewer(m,'source')}<p class="ch-source-caption">${escape(course.sourceTitle||lesson.title)} · 原页图像可放大。${items.length?'右侧分步作答按本关原题组织。':''}</p></div>${items.length?itemView(m):openResponse(m)}</div>${partial(m)?openResponse(m):''}${summary(m)}${answerSection(m)}${!r?.submitted?'<div class="ch-answer-locked"><span>◇</span> 原书答案尚未解锁。先独立作答并提交，再进行对照。</div>':''}</div></div>`}
    function zoomMarkup(){return '<dialog class="ch-zoom-dialog" id="ch-zoom"><div class="ch-zoom-head"><strong id="ch-zoom-title">原页阅读</strong><div><button class="ch-text-link" data-ch-action="zoom-size">查看原尺寸</button><button class="ch-icon-button" data-ch-action="zoom-close" aria-label="关闭原页阅读">×</button></div></div><div class="ch-zoom-stage"><img id="ch-zoom-image" alt="教材原页" decoding="async"></div><div class="ch-zoom-controls"><button class="ch-secondary" data-ch-action="zoom-prev">← 上一页</button><span id="ch-zoom-counter"></span><button class="ch-secondary" data-ch-action="zoom-next">下一页 →</button></div></dialog>'}
    function draw(){if(destroyed)return;host.innerHTML=`<div class="ch-console">${header()}${view==='learn'?learnView():view==='practice'?practiceView():overview()}${zoomMarkup()}</div>`}
    function newResult(m){const old=result(m),items=currentItems(m),auto=items.filter(automatic).length;return {score:0,total:items.length?items.length+(partial(m)?1:0):1,automaticScore:0,automaticTotal:auto,selfScore:0,selfTotal:items.length?items.length-auto+(partial(m)?1:0):1,selfAssessed:false,grading:!auto?'self':auto===items.length&&!partial(m)?'objective':'mixed',reviewNeed:false,submitted:false,status:'in-progress',checked:{},attempt:old?.attempt||1}}
    function ensureResult(m){let r=result(m);if(!r||typeof r!=='object'||!r.checked){r=newResult(m);state.results[missionKey(m)]=r}return r}
    function finishItems(m){const items=currentItems(m),r=ensureResult(m),all=items.every((q,i)=>r.checked[itemKey(q,i)]?.reviewed);r.automaticScore=items.reduce((n,q,i)=>n+(automatic(q)&&r.checked[itemKey(q,i)]?.correct?1:0),0);r.selfScore=items.reduce((n,q,i)=>n+(!automatic(q)&&r.checked[itemKey(q,i)]?.correct?1:0),0)+(partial(m)&&r.groupCorrect?1:0);r.score=r.automaticScore+r.selfScore;r.selfAssessed=Boolean(r.groupAssessed)||items.some((q,i)=>!automatic(q)&&r.checked[itemKey(q,i)]?.reviewed);r.reviewNeed=items.some((q,i)=>r.checked[itemKey(q,i)]?.reviewed&&!r.checked[itemKey(q,i)]?.correct)||(partial(m)&&r.groupAssessed&&!r.groupCorrect);r.itemsSubmitted=all;if(partial(m)){if(!all)r.submitted=false;const finished=all&&r.submitted&&r.groupAssessed;r.status=finished?'complete':r.submitted?'submitted':'in-progress';if(finished){r.finishedAt=new Date().toISOString();award(missionKey(m))}return finished}r.submitted=all;r.status=all?'complete':'in-progress';if(all){r.finishedAt=new Date().toISOString();award(missionKey(m))}return all}
    function checkItem(){const m=missions[missionIndex],q=m.items[itemIndex],key=itemKey(q,itemIndex),value=state.drafts[draftKey(m,key)]||'';if(!answered(m,q,itemIndex)){notify('先填写或选择你的答案。');return}const r=ensureResult(m);if(r.checked[key]?.submitted)return;const auto=automatic(q);r.checked[key]={kind:auto?'auto':'self',response:value,submitted:true,reviewed:auto,correct:auto?same(value,q):null};finishItems(m);save(true);draw()}
    function selfItem(choice){const m=missions[missionIndex],q=m.items[itemIndex],key=itemKey(q,itemIndex),r=ensureResult(m),c=r.checked[key];if(!c?.submitted||automatic(q))return;c.correct=choice==='mastered';c.reviewed=true;finishItems(m);save(true);draw()}
    function nextItem(){const m=missions[missionIndex],items=currentItems(m);if(itemIndex<items.length-1){itemIndex++;persistPosition();draw();return}const next=items.findIndex((q,i)=>!result(m)?.checked?.[itemKey(q,i)]?.reviewed);if(next>=0){itemIndex=next;persistPosition();draw()}else host.querySelector(partial(m)&&!result(m)?.submitted?'.ch-open-response':'#ch-mission-result')?.scrollIntoView({behavior:'smooth',block:'center'})}
    function submitOpen(){const m=missions[missionIndex];if(partial(m)&&!result(m)?.itemsSubmitted){notify('先完成上方分步题，再提交整组作答。');return}const draft=state.drafts[draftKey(m,'response')]||'';if(!draft.trim()){notify('先按原页题号写下你的作答。');return}const r=ensureResult(m);r.submitted=true;r.status='submitted';r.submittedAt=new Date().toISOString();r.selfAssessed=false;r.reviewNeed=false;r.groupAssessed=false;save(true);draw();notify('原书答案已解锁，向下对照后完成自评。')}
    function selfMission(choice){const m=missions[missionIndex],r=result(m);if(!r?.submitted||currentItems(m).length&&!partial(m))return;r.selfAssessed=true;r.reviewNeed=choice!=='mastered';r.groupAssessed=true;r.groupCorrect=choice==='mastered';r.selfScore=(currentItems(m).reduce((n,q,i)=>n+(!automatic(q)&&r.checked?.[itemKey(q,i)]?.correct?1:0),0))+(choice==='mastered'?1:0);r.score=(r.automaticScore||0)+r.selfScore;if(partial(m))r.reviewNeed=r.reviewNeed||currentItems(m).some((q,i)=>r.checked?.[itemKey(q,i)]?.reviewed&&!r.checked[itemKey(q,i)].correct);r.status='complete';r.finishedAt=new Date().toISOString();award(missionKey(m));save(true);draw();notify(choice==='mastered'?'已记录本关自评：掌握。':'已记录为待复习，之后可从地图回来重练。')}
    function retry(m){const r=result(m),attempt=(r?.attempt||0)+1;const next=newResult(m);next.attempt=attempt;state.results[missionKey(m)]=next;for(const q of currentItems(m))state.drafts[draftKey(m,itemKey(q,currentItems(m).indexOf(q))) ]='';state.drafts[draftKey(m,'response')]='';itemIndex=0;answerPage=0;persistPosition();save(false);draw();notify('已开启新一轮练习；历史完成奖励不会重复发放。')}
    function learnNext(){const first=award(`learn:${id}:${step}`);syncRead();save(true);if(first)notify('知识点已完成，继续下一步。');if(step<rules.length-1){move('learn',{step:step+1});return}const missing=rules.findIndex((_,i)=>!learned(i));if(missing>=0){move('learn',{step:missing});return}if(hasBook){continuePractice();notify('学习路径已完成，开始原书挑战。')}else{move('overview');notify('本专题知识点已全部完成。')}}
    function fillZoom(){const m=missions[missionIndex],all=pages(m,zoomKind),index=bounded(zoomKind==='answer'?answerPage:sourcePage,all.length),p=all[index];if(!p)return;const dialog=host.querySelector('#ch-zoom'),img=host.querySelector('#ch-zoom-image');img.src=url(p.src);img.alt=p.label||m.title;img.classList.toggle('is-original',zoomOriginal);host.querySelector('#ch-zoom-title').textContent=p.label||`${zoomKind==='answer'?'答案':'原书'} PDF 第${p.page??index+1}页`;host.querySelector('#ch-zoom-counter').textContent=`${index+1} / ${all.length}`;host.querySelector('[data-ch-action="zoom-size"]').textContent=zoomOriginal?'适应屏幕':'查看原尺寸';dialog.querySelector('[data-ch-action="zoom-prev"]').disabled=index===0;dialog.querySelector('[data-ch-action="zoom-next"]').disabled=index>=all.length-1}
    function openZoom(kind){const m=missions[missionIndex];if(kind==='answer'&&!result(m)?.submitted)return;if(!pages(m,kind).length)return;zoomKind=kind;zoomOriginal=false;fillZoom();const dialog=host.querySelector('#ch-zoom');if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','')}
    function changePage(kind,delta,inZoom=false){const m=missions[missionIndex];if(kind==='answer'&&!result(m)?.submitted)return;if(kind==='answer')answerPage=bounded(answerPage+delta,pages(m,kind).length);else sourcePage=bounded(sourcePage+delta,pages(m,kind).length);persistPosition();if(inZoom)fillZoom();else draw()}
    function onClick(event){const button=event.target.closest?.('[data-ch-action]');if(!button||!host.contains(button)||button.disabled)return;const action=button.dataset.chAction,m=missions[missionIndex];switch(action){case'back':destroy();options.onBack?.();break;case'overview':move('overview');break;case'learn-tab':continueLearning();break;case'practice-tab':continuePractice();break;case'learn-step':move('learn',{step:+button.dataset.index});break;case'previous-step':move('learn',{step:step-1});break;case'learn-next':learnNext();break;case'mission':move('practice',{missionIndex:+button.dataset.index});break;case'item-go':itemIndex=bounded(+button.dataset.index,m.items.length);persistPosition();draw();break;case'check-item':checkItem();break;case'self-item':selfItem(button.dataset.choice);break;case'next-item':nextItem();break;case'edit-item':{const r=ensureResult(m),key=itemKey(m.items[itemIndex],itemIndex);delete r.checked[key];finishItems(m);save(false);draw();break}case'submit-open':submitOpen();break;case'self-mission':selfMission(button.dataset.choice);break;case'retry':{const hasWork=state.drafts[draftKey(m,'response')]||currentItems(m).some((q,i)=>state.drafts[draftKey(m,itemKey(q,i))]);if(!hasWork||window.confirm('重练会清空本关当前作答，并重新隐藏答案。其他关卡和已获得的完成记录保留。继续吗？'))retry(m);break}case'next-mission':missionIndex<missions.length-1?move('practice',{missionIndex:missionIndex+1}):move('overview');break;case'review-toggle':{const r=result(m);if(!r?.submitted||r.status!=='complete')break;r.reviewNeed=!r.reviewNeed;r.selfReviewedAt=new Date().toISOString();save(false);draw();break}case'open-answers':host.querySelector('#ch-answer-section')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'page-prev':changePage(button.dataset.kind,-1);break;case'page-next':changePage(button.dataset.kind,1);break;case'zoom':openZoom(button.dataset.kind);break;case'zoom-close':{const dialog=host.querySelector('#ch-zoom');dialog.close?.();if(!dialog.close)dialog.removeAttribute('open');break}case'zoom-size':zoomOriginal=!zoomOriginal;fillZoom();break;case'zoom-prev':changePage(zoomKind,-1,true);break;case'zoom-next':changePage(zoomKind,1,true);break;case'supplement':options.onSupplement?.();break}}
    function onInput(event){const target=event.target,kind=target.dataset?.chInput;if(!kind)return;const m=missions[missionIndex];if(!m)return;if(kind==='response'){if(result(m)?.submitted)return;state.drafts[draftKey(m,'response')]=target.value;host.querySelector('[data-ch-action="submit-open"]').disabled=!target.value.trim()||(partial(m)&&!result(m)?.itemsSubmitted);host.querySelector('[data-ch-response-count]').textContent=`${target.value.trim().length} 字符`}else if(kind==='item'||kind==='option'){const q=m.items[itemIndex],key=itemKey(q,itemIndex);if(result(m)?.checked?.[key]?.submitted)return;let value=target.value;if(kind==='option'&&multiple(q))value=JSON.stringify([...host.querySelectorAll('[data-ch-input="option"]:checked')].map(input=>input.value));state.drafts[draftKey(m,key)]=value;host.querySelectorAll('.ch-option').forEach(label=>label.classList.toggle('selected',Boolean(label.querySelector('input')?.checked)));const check=host.querySelector('[data-ch-action="check-item"]');if(check)check.disabled=!answered(m,q,itemIndex)}save(false)}
    function onError(event){const img=event.target;if(img.tagName!=='IMG'||!img.closest('.ch-page-image'))return;img.hidden=true;const label=img.closest('.ch-page-image').querySelector('.ch-image-error');if(label)label.hidden=false}
    function destroy(){if(destroyed)return;destroyed=true;abort.abort();host.querySelector('#ch-zoom')?.close?.();instances.delete(host)}
    host.addEventListener('click',onClick,{signal:abort.signal});host.addEventListener('input',onInput,{signal:abort.signal});host.addEventListener('change',event=>{if(event.target.dataset?.chInput==='option')onInput(event)},{signal:abort.signal});host.addEventListener('error',onError,{capture:true,signal:abort.signal});
    const controller={destroy,showOverview:()=>move('overview'),showLearning:continueLearning,showPractice:continuePractice,showMission:index=>move('practice',{missionIndex:index})};instances.set(host,controller);draw();return controller;
  }
  window.StudyChapters={render};
})();
